package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.apache.commons.compress.archivers.tar.TarUtils;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class TarUtils_formatNameBytes_TriageGen0Test {

    /**
     * Mock ZipEncoding to control the ByteBuffer returned.
     */
    private static class TestEncoding implements ZipEncoding {
        @Override
        public ByteBuffer encode(String s) {
            return ByteBuffer.wrap(s.getBytes(StandardCharsets.UTF_8));
        }
    }

    @Test
    public void testFormatNameBytes_ExactLength() throws IOException {
        String name = "test.txt";
        byte[] buf = new byte[10];
        int offset = 0;
        int length = 8;
        ZipEncoding encoding = new TestEncoding();

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(offset + length, result);
        assertEquals("test.txt", new String(buf, 0, 8, StandardCharsets.UTF_8));
    }

    @Test
    public void testFormatNameBytes_PaddingRequired() throws IOException {
        String name = "abc";
        byte[] buf = new byte[10];
        int offset = 0;
        int length = 5;
        ZipEncoding encoding = new TestEncoding();

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(5, result);
        assertEquals('a', buf[0]);
        assertEquals('b', buf[1]);
        assertEquals('c', buf[2]);
        assertEquals(0, buf[3]);
        assertEquals(0, buf[4]);
    }

    @Test
    public void testFormatNameBytes_TruncateByLength() throws IOException {
        String name = "verylongname";
        byte[] buf = new byte[5];
        int offset = 0;
        int length = 5;
        ZipEncoding encoding = new TestEncoding();

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(5, result);
        assertEquals("veryl", new String(buf, 0, 5, StandardCharsets.UTF_8));
    }

    @Test
    public void testFormatNameBytes_TruncateBySubstringLoop() throws IOException {
        // We simulate a case where the encoding produces more bytes than allowed, 
        // forcing the while loop to reduce the string length.
        ZipEncoding mockEncoding = mock(ZipEncoding.class);
        String name = "abc";

        // First call: "abc" -> 3 bytes. If length is 2, it must loop.
        // Second call: "ab" -> 2 bytes.
        when(mockEncoding.encode("abc")).thenReturn(ByteBuffer.wrap(new byte[]{1, 2, 3}));
        when(mockEncoding.encode("ab")).thenReturn(ByteBuffer.wrap(new byte[]{1, 2}));
        when(mockEncoding.encode("a")).thenReturn(ByteBuffer.wrap(new byte[]{1}));

        byte[] buf = new byte[5];
        int offset = 0;
        int length = 2;

        int result = TarUtils.formatNameBytes(name, buf, offset, length, mockEncoding);

        assertEquals(2, result);
        assertEquals(1, buf[0]);
        assertEquals(2, buf[1]);
    }

    @Test
    public void testFormatNameBytes_EmptyName() throws IOException {
        String name = "";
        byte[] buf = new byte[5];
        int offset = 0;
        int length = 5;
        ZipEncoding encoding = new TestEncoding();

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(5, result);
        for (int i = 0; i < 5; i++) {
            assertEquals(0, buf[i]);
        }
    }

    @Test
    public void testFormatNameBytes_WithOffset() throws IOException {
        String name = "hi";
        byte[] buf = new byte[10];
        int offset = 3;
        int length = 2;
        ZipEncoding encoding = new TestEncoding();

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(5, result);
        assertEquals('h', buf[3]);
        assertEquals('i', buf[4]);
        assertEquals(0, buf[5]); // Padding check
    }

    @Test
    public void testFormatNameBytes_EncodingThrowsException() throws IOException {
        ZipEncoding mockEncoding = mock(ZipEncoding.class);
        when(mockEncoding.encode(anyString())).thenThrow(new IOException("Encoding error"));

        byte[] buf = new byte[10];
        try {
            TarUtils.formatNameBytes("test", buf, 0, 5, mockEncoding);
            org.junit.Assert.fail("Should have thrown IOException");
        } catch (IOException e) {
            assertEquals("Encoding error", e.getMessage());
        }
    }

    @Test
    public void testFormatNameBytes_AllCharactersRemoved() throws IOException {
        // Case where even a single character is too long (unlikely with UTF-8 but possible with custom encoding)
        ZipEncoding mockEncoding = mock(ZipEncoding.class);
        String name = "a";

        // "a" encodes to 2 bytes, but length requested is 1. 
        // Loop reduces len to 0.
        when(mockEncoding.encode("a")).thenReturn(ByteBuffer.wrap(new byte[]{1, 2}));
        when(mockEncoding.encode("")).thenReturn(ByteBuffer.wrap(new byte[]{}));

        byte[] buf = new byte[1];
        int result = TarUtils.formatNameBytes(name, buf, 0, 1, mockEncoding);

        assertEquals(1, result);
        assertEquals(0, buf[0]);
    }
}
